import{z as A,x as p,o as s,c as o,q as r,j as n,D as B,d as E,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"匿名页对文件页","description":"","frontmatter":{"title":"匿名页对文件页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/anon-vs-file-page.md","filePath":"cs/anon-vs-file-page.md","lastUpdated":1791413859000}'),d={name:"cs/anon-vs-file-page.md"};function m(C,a,F,D,f,h){const t=p("Mermaid");return s(),o("div",null,[a[2]||(a[2]=r('<h1 id="匿名页对文件页" tabindex="-1">匿名页对文件页 <a class="header-anchor" href="#匿名页对文件页" aria-label="Permalink to &quot;匿名页对文件页&quot;">​</a></h1><div class="epigraph"><p>文件页扔掉还能从文件再读；匿名页没有文件副本，脏了就必须进交换区，否则内容消失。</p><footer>—— 据 Silberschatz et al.；Bovet and Cesati 对 Linux 页来源的整理</footer></div><p><a href="/cs/thrashing">上一课</a>把所有页算进工作集。<a href="/cs/page-fault-path">缺页路径</a>已经能从文件填页或填零。<a href="/cs/page-replace">置换</a>说只读文本可丢弃。缺口是钉死两类<strong>后备</strong>：文件页（inode + 偏移）与匿名页（堆、栈、匿名 mmap、COW 私有副本）。CLOCK 扫描到它们时，写回目标不是同一个设备。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把文本页写进 swap，浪费交换槽且与可执行文件重复。若把改过的堆页只标无效而不写出，进程稍后读到的是空洞或别人的帧。缺口不是再讲 VMA，而是页描述符上的来源：文件映射指向 <a href="/cs/vfs">VFS</a> 之后才完全展开的 inode；匿名页指向交换槽或「尚无槽的脏匿名」。干净文件页：解映射即可。脏文件页：写回文件。脏匿名页：写 swap。</p><p><span class="marginnote">术语翻译：「后备」（backing store）指页被挤出内存后内容的容身之处。匿名页就是「没有名字」的页——不对应任何文件，堆、栈、匿名 mmap、写时复制的私有副本都是；它们的后备只能是交换区，因为没有第二个地方能重新读出这些内容。</span></p><p>本课不把 shmem/tmpfs 的全部特例写完，只承认它们像「有文件外形的匿名」。</p><p><span class="marginnote">同一物理页可被文件映射共享。淘汰时要看映射类型与脏位，不能只看 CLOCK 指针。后课 mmap 会把共享/私有写清楚；本课先分后备设备。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缺页填页时记录 mapping。置换选中：查来源。文件且干净 → 丢；文件且脏 → 加入对文件系统的回写（缓冲课）。匿名且干净（如未写过的零页）→ 丢；匿名且脏 → 分配交换槽、写交换设备。之后 PTE 改为「不在内存」，编码里带槽号或再缺页时查换出表。</p><p><span class="marginnote">直觉类比：干净文件页像图书馆的书——用完直接还回书架（丢弃），谁要再借随时有；脏匿名页像你的手写草稿——世上没有第二份，想腾桌面就必须先拍照存档（写 swap），之后要看再调出来。两者「归还成本」天差地别。</span></p>',11)),(s(),n(i,null,{default:B(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20VIC%5B%22%E7%89%BA%E7%89%B2%E9%A1%B5%22%5D%20--%3E%20F%7B%22%E6%96%87%E4%BB%B6%3F%22%7D%0A%20%20F%20--%3E%7C%E5%B9%B2%E5%87%80%7C%20DROP%5B%22%E4%B8%A2%2C%20%E5%86%8D%E8%AF%BB%E6%96%87%E4%BB%B6%22%5D%0A%20%20F%20--%3E%7C%E8%84%8F%7C%20FB%5B%22%E5%86%99%E5%9B%9E%E6%96%87%E4%BB%B6%22%5D%0A%20%20VIC%20--%3E%20A%5B%22%E5%8C%BF%E5%90%8D%E8%84%8F%22%5D%0A%20%20A%20--%3E%20SW%5B%22%E5%86%99%20swap%20%E6%A7%BD%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("分类让抖动对策更细：优先丢干净文件页，等于用磁盘文件当免费后备；匿名压力才真正吃 swap。工作集里的堆页因此「更贵」。不要在此展开 ext4 布局；文件只是可再次 "),e("code",null,"readpage"),E(" 的对象。"),e("a",{href:"/cs/paging-vm"},"分页"),E(" 仍然只看见有效位；来源在内核页框数据结构里。")],-1)),a[5]||(a[5]=e("p",null,"两类页从出生到被淘汰走的路完全不同，淘汰代价也随之分档：",-1)),(s(),n(i,null,{default:B(()=>[l(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANON%5B%22%E5%8C%BF%E5%90%8D%E9%A1%B5%EF%BC%9A%E5%A0%86%20%2F%20%E6%A0%88%20%2F%20COW%20%E7%A7%81%E6%9C%89%E5%89%AF%E6%9C%AC%22%5D%20--%3E%20ZF%5B%22%E7%BC%BA%E9%A1%B5%E6%97%B6%E5%A1%AB%E9%9B%B6%E6%88%96%E5%A4%8D%E5%88%B6%22%5D%0A%20%20ZF%20--%3E%20D1%5B%22%E4%B8%80%E6%97%A6%E5%86%99%E5%85%A5%E5%8D%B3%E8%84%8F%EF%BC%9A%E5%86%85%E5%AD%98%E9%87%8C%E6%98%AF%E5%94%AF%E4%B8%80%E5%89%AF%E6%9C%AC%22%5D%0A%20%20D1%20--%3E%20SW%5B%22%E8%A2%AB%E6%B7%98%E6%B1%B0%E5%BF%85%E9%A1%BB%E5%86%99%20swap%EF%BC%9A4%20KB%20%E4%B8%80%E6%AC%A1%20I%2FO%22%5D%0A%20%20SW%20--%3E%20RB%5B%22%E8%BF%9B%E7%A8%8B%E5%86%8D%E8%AE%BF%E9%97%AE%EF%BC%9A%E5%86%8D%E8%8A%B1%E4%B8%80%E6%AC%A1%20I%2FO%20%E8%AF%BB%E5%9B%9E%E6%9D%A5%22%5D%0A%20%20FILE%5B%22%E6%96%87%E4%BB%B6%E9%A1%B5%EF%BC%9A%E4%BB%A3%E7%A0%81%20%2F%20%E5%8F%AA%E8%AF%BB%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20CL%5B%22%E6%B2%A1%E6%94%B9%E8%BF%87%EF%BC%9A%E7%9B%B4%E6%8E%A5%E4%B8%A2%E5%BC%83%EF%BC%8C%E9%9B%B6%20I%2FO%22%5D%0A%20%20FILE%20--%3E%20WB%5B%22%E6%94%B9%E8%BF%87%EF%BC%9A%E5%86%99%E5%9B%9E%E5%8E%9F%E6%96%87%E4%BB%B6%EF%BC%8C%E5%86%85%E5%AE%B9%E4%BB%8D%E6%9C%89%E5%90%8D%E5%AD%97%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">为什么重要：淘汰一页干净文件页的 I/O 代价是零（解映射即可），而淘汰一页脏匿名页至少两次 I/O——现在写出去、将来读回来。所以内核内存紧张时先回收页缓存里的干净文件页，swap 被真正动用往往意味着物理内存已经见底。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入交换分区的条带与优先级全文。不把设备页（framebuffer）混进匿名。文件空洞与稀疏文件在缺页时可能填零，仍算文件来源。下一课才问 swap 设备长什么样、槽如何分配。</p><p>后课默认：匿名脏页必须有交换去处。槽在哪、如何成设备，下一课 swap。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文件页以文件为后备；匿名脏页以 swap 为后备。</li><li>淘汰代价不同，工作集会计应分开看。</li><li>交换槽与设备是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Bovet and Cesati, <em>ULK</em>；Tanenbaum <em>MOS</em>。</li></ul>',6))])}const g=A(d,[["render",m]]);export{u as __pageData,g as default};
